import React, { useState, useEffect } from "react";
import { navigate } from "gatsby";
import { FaUser, FaLock, FaEye, FaEyeSlash, FaExclamationTriangle, FaImage, FaClipboardList, FaBolt, FaArrowRight } from "react-icons/fa";
import { login, useOpenbase } from "../ppm/openbase/openbase";
import { BRANDING } from "../ppm/cfimages/branding";

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);
  const [shake, setShake] = useState(false);

  // If the user already has a valid token, skip straight to the dashboard.
  const { loading: authLoading, openbase: authed } = useOpenbase();
  useEffect(() => {
    if (!authLoading && authed) navigate("/dashboard", { replace: true });
  }, [authLoading, authed]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setErr("");
    try {
      await login(email.trim(), pass);
      navigate("/dashboard", { replace: true });
    } catch (err: any) {
      const msg =
        err?.data?.error ||
        err?.data?.message ||
        (typeof err?.data === "string" ? err.data : "") ||
        err?.message ||
        "Invalid email or password.";
      setErr(msg);
      setShake(true);
      setTimeout(() => setShake(false), 500);
      setLoading(false);
    }
  };

  return (
    <div style={s.page}>
      <style>{css}</style>

      {/* Left panel */}
      <div style={s.left}>
        <div style={s.leftInner}>
         
          <h1 style={s.leftTitle}>{BRANDING.name}<br />{BRANDING.tagline}</h1>
          <p style={s.leftSub}>Manage your website content, images, and more — all in one place.</p>
          <div style={s.features}>
            {([
              [<FaImage />, "Image Gallery Management"],
              [<FaClipboardList />, "Content Updates"],
              [<FaBolt />, "Fast & Secure Access"],
            ] as [React.ReactNode, string][]).map(([icon, label]) => (
              <div key={label} style={s.feature}>
                <span style={s.featureIcon}>{icon}</span>
                {label}
              </div>
            ))}
          </div>
        </div>
        <div style={s.roofShape} />
      </div>

      {/* Right panel */}
      <div style={s.right}>
        <div style={{ ...s.card, animation: shake ? "shake 0.4s ease" : "fadeUp 0.5s ease both" }}>
        
          <h2 style={s.title}>Welcome back</h2>
          <p style={s.subtitle}>{BRANDING.cardSubtitle}</p>

          <form onSubmit={handleSubmit} style={s.form}>
            {/* Email */}
            <div style={s.fieldWrap}>
              <span style={s.fieldIcon}><FaUser size={14} /></span>
              <input
                style={s.input}
                type="email"
                placeholder="Email"
                value={email}
                onChange={e => { setEmail(e.target.value); setErr(""); }}
                required
                autoComplete="email"
              />
            </div>

            {/* Password */}
            <div style={s.fieldWrap}>
              <span style={s.fieldIcon}><FaLock size={14} /></span>
              <input
                style={{ ...s.input, paddingRight: 44 }}
                type={showPass ? "text" : "password"}
                placeholder="Password"
                value={pass}
                onChange={e => { setPass(e.target.value); setErr(""); }}
                required
                autoComplete="current-password"
              />
              <button
                type="button"
                style={s.eyeBtn}
                onClick={() => setShowPass(p => !p)}
                tabIndex={-1}
              >
                {showPass ? <FaEyeSlash size={15} /> : <FaEye size={15} />}
              </button>
            </div>

            {err && (
              <div style={s.errBox}>
                <FaExclamationTriangle size={13} /> {err}
              </div>
            )}

            <button style={{ ...s.btn, opacity: loading ? 0.75 : 1 }} type="submit" disabled={loading}>
              {loading ? <span style={s.spinner} className="spin" /> : null}
              {loading ? "Signing in…" : <><span>Sign In</span><FaArrowRight size={13} /></>}
            </button>
          </form>

          <p style={s.hint}>Need access? Contact your admin.</p>
        </div>
      </div>
    </div>
  );
};

